CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assigned_to_user_id BIGINT UNSIGNED NOT NULL, created_by_user_id BIGINT UNSIGNED NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium', status ENUM('todo','in_progress','completed','cancelled') NOT NULL DEFAULT 'todo', due_at DATETIME NULL, completed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_tasks_assignee_status_due (assigned_to_user_id,status,due_at), CONSTRAINT fk_tasks_assignee FOREIGN KEY (assigned_to_user_id) REFERENCES users(id) ON DELETE RESTRICT, CONSTRAINT fk_tasks_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
